message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "Your heart does not pump as strongly as it should. The pumping power is 30%.",
          "sources": ["p1:L6", "term:CHF", "term:EF"]
        },
        {
          "id": "b2",
          "text": "You have narrowed blood vessels in the heart. You had a procedure to open a blocked heart artery.",
          "sources": ["p1:L7", "term:CAD", "term:PCI"]
        },
        {
          "id": "b3",
          "text": "You also have high blood pressure.",
          "sources": ["p1:L7", "term:HTN"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b4",
          "text": "Eat a low salt diet. Limit salt to 2 grams each day.",
          "sources": ["p1:L19"]
        },
        {
          "id": "b5",
          "text": "Drink no more than 1.5 liters of fluid each day.",
          "sources": ["p1:L19"]
        },
        {
          "id": "b6",
          "text": "Weigh yourself every morning before breakfast. Write the number down.",
          "sources": ["p1:L20"]
        },
        {
          "id": "b7",
          "text": "Do not lift anything heavier than 10 pounds for one week.",
          "sources": ["p1:L21"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b8",
          "text": "See Dr. Okafor, your heart doctor. Go in one week. This visit checks your heart.",
          "sources": ["p1:L23"]
        },
        {
          "id": "b9",
          "text": "Get a blood test for salts and kidneys. Go in three days. This checks your potassium and kidney function.",
          "sources": ["p1:L24", "term:BMP"]
        },
        {
          "id": "b10",
          "text": "See your family doctor. Go in two weeks. This visit checks your overall health.",
          "sources": ["p1:L25", "term:PCP"]
        }
      ]
    }
  ],
  "questions_for_your_doctor": [
    "What should I do if my weight goes up quickly?",
    "Can I change my salt or fluid limits?",
    "When will I know the results of my blood test?"
  ]
}
